export const ALL_CORRIDOR_INCIDENTS = CORRIDORS_LIST.flatMap((corridor) =>
  (corridor.incidents || []).map((inc) => ({
    ...inc,
    corridorId: corridor.id,
    corridorCode: corridor.code,
    corridorName: corridor.name,
    corridorShortName: corridor.shortName,
  }))
);

export function getCorridorById(id) {
  if (!id) return CORRIDORS_LIST[0];
  const clean = String(id).trim().toUpperCase();

  // 1. Direct match on id or code
  const exact = CORRIDORS_LIST.find((c) => c.id.toUpperCase() === clean || c.code.toUpperCase() === clean);
  if (exact) return exact;

  // 2. Number match e.g. "01" -> "CORRIDOR-01" or "1"
  const numMatch = clean.match(/\b(\d{1,2})\b/);
  if (numMatch) {
    const num = parseInt(numMatch[1], 10);
    const numPadded = num < 10 ? '0' + num : String(num);
    const matchByNum = CORRIDORS_LIST.find((c) => 
      c.id === 'CORRIDOR-' + numPadded || 
      c.corridorOrder === num || 
      c.code === 'COR ' + numPadded
    );
    if (matchByNum) return matchByNum;
  }

  // 3. Partial substring search
  const partial = CORRIDORS_LIST.find((c) =>
    c.name.toUpperCase().includes(clean) ||
    c.shortName.toUpperCase().includes(clean) ||
    (c.keyLocations && c.keyLocations.toUpperCase().includes(clean))
  );
  if (partial) return partial;

  return CORRIDORS_LIST[0];
}
